function validate([obstacles]) {
  if (!Array.isArray(obstacles) || obstacles.length < 2 || obstacles.length > 500001) return 'obstacles needs 2 to 500001 values (n from 1 to 5 * 10^5).';
  if (obstacles.some(v => !Number.isInteger(v) || v < 0 || v > 3)) return 'Each value of obstacles is 0, 1, 2 or 3.';
  if (obstacles[0] !== 0 || obstacles[obstacles.length - 1] !== 0) return 'The first and last points must be clear (0).';
  return null;
}

