function minSideJumps(obstacles) {
  const dp = [1, 0, 1];
  for (let i = 1; i < obstacles.length; i++) {
    const blocked = obstacles[i] - 1;
    if (blocked >= 0) {
      dp[blocked] = Infinity;
    }
    const best = Math.min(...dp);
    for (let lane = 0; lane < 3; lane++) {
      if (lane !== blocked) {
        dp[lane] = Math.min(dp[lane], best + 1);
      }
    }
  }
  return Math.min(...dp);
}

