function minSideJumps(obstacles) {
  // Shortest path over (point, lane) states: relax every move until nothing improves.
  const n = obstacles.length - 1;
  const open = (point, lane) => obstacles[point] !== lane;
  const dist = Array.from({ length: n + 1 }, () => [Infinity, Infinity, Infinity, Infinity]);
  dist[0][2] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let point = 0; point <= n; point++) {
      for (let lane = 1; lane <= 3; lane++) {
        const d = dist[point][lane];
        if (d === Infinity) continue;
        if (point < n && open(point + 1, lane) && d < dist[point + 1][lane]) { dist[point + 1][lane] = d; changed = true; }
        for (let other = 1; other <= 3; other++) {
          if (other !== lane && open(point, other) && d + 1 < dist[point][other]) { dist[point][other] = d + 1; changed = true; }
        }
      }
    }
  }
  return Math.min(dist[n][1], dist[n][2], dist[n][3]);
}

