function generate(rand, size) {
  const n = size === 'large' ? 1999 : 1 + Math.floor(rand() * 9);
  const density = rand();
  const obstacles = [0];
  for (let i = 1; i < n; i++) obstacles.push(rand() < density ? 1 + Math.floor(rand() * 3) : 0);
  obstacles.push(0);
  return [obstacles];
}
